    for r in range(1, h - 1):
        for c in range(1, w - 1):
            col = g[r][c]
            if col != g[0][0]:
                # Locate axis-aligned hollow rectangular outlines by their bounds.
                pass
    # A 3x3 ring object has its center recolored to the next color.
    bg = grid[0][0]
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r-1][c]
            if color != bg and grid[r+1][c] == color and grid[r][c-1] == color and grid[r][c+1] == color and grid[r][c] == bg:
                if all(grid[rr][cc] == color for rr in (r-1,r+1) for cc in (c-1,c+1)):
                    g[r][c] = (color + 1) % 10
    # Identify rectangular frames from same-color horizontal/vertical borders.
    for color in set(v for row in grid for v in row):
        if color == g[0][0]:
            continue
        for r1 in range(h):
            for r2 in range(r1 + 2, h):
                for c1 in range(w):
                    for c2 in range(c1 + 2, w):
                        if (all(g[r1][c] == color for c in range(c1,c2+1)) and
                            all(g[r2][c] == color for c in range(c1,c2+1)) and
                            all(g[r][c1] == color for r in range(r1,r2+1)) and
                            all(g[r][c2] == color for r in range(r1,r2+1))):
                            for r in range(r1+1,r2):
                                for c in range(c1+1,c2):
                                    if g[r][c] == g[0][0]:
                                        g[r][c] = (color - 1) % 10
    return g

