 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Enclosed rectangular regions are recolored by interior area: small
    # cavities become 7, larger cavities become 2.
    for color in set(v for row in grid for v in row):
        if color == grid[0][0]:
            continue
        for r1 in range(h):
            for r2 in range(r1 + 2, h):
                for c1 in range(w):
                    for c2 in range(c1 + 2, w):
                        if (all(grid[r1][c] == color for c in range(c1,c2+1)) and
                            all(grid[r2][c] == color for c in range(c1,c2+1)) and
                            all(grid[r][c1] == color for r in range(r1,r2+1)) and
                            all(grid[r][c2] == color for r in range(r1,r2+1))):
                            area = (r2-r1-1)*(c2-c1-1)
                            fill = 2 if area >= 16 else 7
                            for r in range(r1+1,r2):
                                for c in range(c1+1,c2):
                                    g[r][c] = fill
    # A single-cell hole surrounded by a 3x3 ring always becomes 7.
    bg = grid[0][0]
    for r in range(1,h-1):
        for c in range(1,w-1):
            color = grid[r-1][c]
            if (color != bg and grid[r+1][c] == color and
                grid[r][c-1] == color and grid[r][c+1] == color and
                grid[r][c] == bg and
                all(grid[rr][cc] == color for rr in (r-1,r+1) for cc in (c-1,c+1))):
                g[r][c] = 7
    return g
